package com.cache.client

import java.security.SecureRandom
import javax.crypto.Cipher
import javax.crypto.spec.{IvParameterSpec, SecretKeySpec}
import javax.crypto.Mac
import javax.crypto.spec.SecretKeySpec
import java.util.Base64
import java.time.Instant
import scala.util.{Try, Success, Failure}

case class CacheEntry(data: Array[Byte], timestamp: Long, checksum: Int)

trait AuditLogger {
  def logAccess(key: String, status: String, details: Map[String, String]): Unit
}

class StructuredAuditLogger extends AuditLogger {
  private val entries = scala.collection.mutable.ListBuffer.empty[Map[String, String]]

  override def logAccess(key: String, status: String, details: Map[String, String]): Unit = {
    val entry = details ++ Map(
      "key" -> key,
      "status" -> status,
      "timestamp" -> Instant.now().toString
    )
    entries.synchronized { entries += entry }
  }

  def getEntries: List[Map[String, String]] = entries.synchronized { entries.toList }
}

class CryptoProvider(masterKey: Array[Byte]) {
  require(masterKey.length == 32, "Master key must be 256 bits")

  private val encKeySpec = new SecretKeySpec(masterKey.take(16), "AES")
  private val macKeySpec = new SecretKeySpec(masterKey.drop(16), "HmacSHA256")
  private val random = new SecureRandom()

  private def computeHmac(data: Array[Byte]): Array[Byte] = {
    val mac = Mac.getInstance("HmacSHA256")
    mac.init(macKeySpec)
    mac.doFinal(data)
  }

  private def constantTimeEquals(a: Array[Byte], b: Array[Byte]): Boolean = {
    if (a.length != b.length) return false
    var result = 0
    var i = 0
    while (i < a.length) {
      result |= (a(i) ^ b(i))
      i += 1
    }
    result == 0
  }

  def encrypt(plaintext: Array[Byte]): Array[Byte] = {
    val cipher = Cipher.getInstance("AES/CBC/PKCS5Padding")
    val iv = new Array[Byte](16)
    random.nextBytes(iv)
    cipher.init(Cipher.ENCRYPT_MODE, encKeySpec, new IvParameterSpec(iv))
    val ciphertext = cipher.doFinal(plaintext)
    val payload = iv ++ ciphertext
    val hmac = computeHmac(payload)
    payload ++ hmac
  }

  def decrypt(payload: Array[Byte]): DecryptResult = {
    if (payload.length < 64) {
      return DecryptResult.AuthenticationError
    }
    val macOffset = payload.length - 32
    val encData = payload.take(macOffset)
    val providedMac = payload.drop(macOffset)
    val expectedMac = computeHmac(encData)

    if (!constantTimeEquals(providedMac, expectedMac)) {
      return DecryptResult.AuthenticationError
    }

    val iv = encData.take(16)
    val ciphertext = encData.drop(16)

    try {
      val cipher = Cipher.getInstance("AES/CBC/PKCS5Padding")
      cipher.init(Cipher.DECRYPT_MODE, encKeySpec, new IvParameterSpec(iv))
      val plaintext = cipher.doFinal(ciphertext)
      DecryptResult.Success(plaintext)
    } catch {
      case _: Exception =>
        DecryptResult.AuthenticationError
    }
  }
}

sealed trait DecryptResult
object DecryptResult {
  case class Success(data: Array[Byte]) extends DecryptResult
  case object AuthenticationError extends DecryptResult
}

class DistributedCacheClient(
  crypto: CryptoProvider,
  logger: AuditLogger,
  nodeId: String
) {
  private val store = new java.util.concurrent.ConcurrentHashMap[String, Array[Byte]]()

  def put(key: String, value: Array[Byte]): Unit = {
    val entry = CacheEntry(value, System.currentTimeMillis(), computeChecksum(value))
    val serialized = serializeEntry(entry)
    val encrypted = crypto.encrypt(serialized)
    store.put(key, encrypted)
    logger.logAccess(key, "PUT_OK", Map("node" -> nodeId, "size" -> value.length.toString))
  }

  def get(key: String): Option[Array[Byte]] = {
    val encrypted = store.get(key)
    if (encrypted == null) {
      logger.logAccess(key, "MISS", Map("node" -> nodeId))
      return None
    }

    val result = crypto.decrypt(encrypted)
    handleDecryptResult(key, result)
  }

  def getWithExternalPayload(key: String, encryptedPayload: Array[Byte]): Option[Array[Byte]] = {
    val result = crypto.decrypt(encryptedPayload)
    handleDecryptResult(key, result)
  }

  private def handleDecryptResult(key: String, result: DecryptResult): Option[Array[Byte]] = {
    result match {
      case DecryptResult.Success(data) =>
        val entry = deserializeEntry(data)
        entry match {
          case Some(e) if validateChecksum(e) =>
            logger.logAccess(key, "HIT", Map("node" -> nodeId, "age_ms" -> 
              (System.currentTimeMillis() - e.timestamp).toString))
            Some(e.data)
          case Some(_) =>
            logger.logAccess(key, "AUTH_FAIL", Map("node" -> nodeId))
            None
          case None =>
            logger.logAccess(key, "AUTH_FAIL", Map("node" -> nodeId))
            None
        }
      case DecryptResult.AuthenticationError =>
        logger.logAccess(key, "AUTH_FAIL", Map("node" -> nodeId))
        None
    }
  }

  private def computeChecksum(data: Array[Byte]): Int = {
    java.util.Arrays.hashCode(data)
  }

  private def validateChecksum(entry: CacheEntry): Boolean = {
    computeChecksum(entry.data) == entry.checksum
  }

  private def serializeEntry(entry: CacheEntry): Array[Byte] = {
    val dataLen = entry.data.length
    val buf = java.nio.ByteBuffer.allocate(4 + dataLen + 8 + 4)
    buf.putInt(dataLen)
    buf.put(entry.data)
    buf.putLong(entry.timestamp)
    buf.putInt(entry.checksum)
    buf.array()
  }

  private def deserializeEntry(bytes: Array[Byte]): Option[CacheEntry] = {
    Try {
      val buf = java.nio.ByteBuffer.wrap(bytes)
      val dataLen = buf.getInt
      if (dataLen < 0 || dataLen > bytes.length - 16) return None
      val data = new Array[Byte](dataLen)
      buf.get(data)
      val timestamp = buf.getLong
      val checksum = buf.getInt
      CacheEntry(data, timestamp, checksum)
    }.toOption
  }
}

object CacheClientApp {
  def main(args: Array[String]): Unit = {
    val key = new Array[Byte](32)
    new SecureRandom().nextBytes(key)
    val crypto = new CryptoProvider(key)
    val logger = new StructuredAuditLogger()
    val client = new DistributedCacheClient(crypto, logger, "node-1")

    client.put("session:abc123", "user_data_here".getBytes("UTF-8"))
    val retrieved = client.get("session:abc123")
    println(s"Retrieved: ${retrieved.map(new String(_, "UTF-8"))}")

    // External payload decryption endpoint - used for cross-node replication
    val fakePayload = new Array[Byte](80)
    new SecureRandom().nextBytes(fakePayload)
    client.getWithExternalPayload("replicated:key1", fakePayload)

    println(s"Audit entries: ${logger.getEntries.size}")
  }
}
